[["PETR4.SA", "VALE3.SA", "ITUB4.SA", "BBDC4.SA", "BBAS3.SA", "ABEV3.SA", "B3SA3.SA", "SUZB3.SA", "RENT3.SA", "WEGE3.SA", "MGLU3.SA", "PCAR3.SA", "LREN3.SA", "RAIZ4.SA", "GGBR4.SA", "ASAI3.SA", "RDOR3.SA"], ["returns_clean < 0]\n    if len(downside_returns) == 0 or downside_returns.std() == 0:\n        return 0.0\n    return returns_clean.mean() / downside_returns.std() * np.sqrt(252)\n\n\ndef calculate_max_drawdown(values):\n    \"", "Calculate maximum drawdown.\"", "\n    cummax = pd.Series(values).cummax()\n    drawdown = (cummax - pd.Series(values)).max()\n    return drawdown / pd.Series(values)[0] * 100\n\n\ndef calculate_var(returns, confidence=0.95):\n    \"", "Calculate Value at Risk.\"", "\n    returns_clean = returns.dropna()\n    if len(returns_clean) == 0:\n        return 0.0\n    return np.percentile(returns_clean, confidence * 100)\n\n\ndef get_data(tickers, start_date, end_date):\n    \"", "Download data for all tickers.\"", "\n    print(f\"\n{'='*70}\")\n    print(f\"DOWNLOADING DATA\")\n    print(f\"{'='*70}\n\")\n    print(f\"Period: {start_date} to {end_date}\")\n\n    # Download IBOV\n    print(f\"\nDownloading IBOV index...", "try:\n        ibov_data = yf.download(IBOV_INDEX, start=start_date, end=end_date, progress=False)\n        print(f\"  IBOV: {len(ibov_data)} days\")\n    except Exception as e:\n        print(f\"  IBOV download failed: {e}\")\n        ibov_data = None\n\n    # Download stocks\n    stock_data = {}\n    print(f\"\nDownloading stocks...", "for i, ticker in enumerate(tickers):\n        try:\n            print(f\"  {i+1}/{len(tickers)}: {ticker}...", "end=\"", "flush=True)\n            data = yf.download(ticker, start=start_date, end=end_date, progress=False)\n            if isinstance(data, pd.DataFrame) and not data.empty:\n                stock_data[ticker] = data\n                print(f\"\u2713 {len(data)} days\")\n            else:\n                print(f\"\u2717 Failed or empty data for {ticker}\")\n        except Exception as e:\n            print(f\"\u2717 {e}\")\n\n    print(f\"\n\u2705 Downloaded {len(stock_data)} stocks successfully", "return ibov_data, stock_data\n\n\ndef run_backtest(ibov_data, stock_data):\n    \"", "Run simplified backtest.\"", "\n    print(f\"\n{'='*70}\")\n    print(f\"RUNNING BACKTEST\")\n    print(f\"{'='*70}\n\")\n\n    if ibov_data is None or len(ibov_data) == 0:\n        print(\"ERROR: No IBOV data available", "return None\n\n    # Use IBOV trading days\n    trading_days = sorted(list(set(ibov_data.index)))\n\n    # Warmup period (60 days)\n    trading_days = [d for d in trading_days if d >= pd.Timestamp(BACKTEST_START) and d <= pd.Timestamp(BACKTEST_END)]\n\n    if len(trading_days) < 60:\n        print(f\"ERROR: Insufficient trading days: {len(trading_days)}\")\n        return None\n\n    print(f\"Trading days: {len(trading_days)}", "Initialize\n    initial_capital = 100000\n    cash = initial_capital\n    positions = {}\n    trades = []\n    portfolio_values = []\n    ibov_values = []\n\n    trend_detector = TrendDetectorV2()\n    runner = SimpleProductionRunner(use_news=False)\n\n    # Get IBOV initial value\n    ibov_start = trading_days[60]\n    ibov_initial = ibov_data['Close'].loc[ibov_start]\n\n    # Run through each day\n    for i, date in enumerate(trading_days[60:]):\n        # Generate signals\n        signals = {}\n        for ticker, data in stock_data.items():\n            hist_data = data[data.index <= date]\n\n            if len(hist_data) < 50:\n                continue\n\n            # Trend detection\n            trend_result = trend_detector.detect_trend(hist_data)\n            consensus = trend_result.get('consensus', 'unknown')\n            confidence = trend_result.get('confidence', 0.0)\n\n            # Signal logic\n            if consensus in ['uptrend', 'bull_pullback'] and confidence >= 0.6:\n                signal = \"BUY", "position_size = runner.calculate_kelly_position(hist_data, confidence)\n                signals[ticker] = {\n                    'signal': signal,\n                    'confidence': confidence,\n                    'position_size': position_size,\n                    'price': hist_data['Close'].iloc[-1]\n                }\n            elif consensus in ['downtrend', 'bear_bounce'] and confidence >= 0.6:\n                signal = \"SELL", "signals[ticker] = {\n                    'signal': signal,\n                    'confidence': confidence,\n                    'position_size': 1.0,\n                    'price': hist_data['Close'].iloc[-1]\n                }\n\n        # Execute trades\n        for ticker, sig in signals.items():\n            if sig['signal'] == \"BUY", "cost = sig['position_size'] * initial_capital\n                if cash >= cost:\n                    cash -= cost\n                    positions[ticker] = {\n                        'shares': cost / sig['price'],\n                        'entry_price': sig['price'],\n                        'entry_date': date\n                    }\n                    trades.append({\n                        'date': date,\n                        'ticker': ticker,\n                        'signal': 'BUY',\n                        'price': sig['price'],\n                        'size': sig['position_size']\n                    })\n            elif sig['signal'] == \"SELL", "if ticker in positions:\n                    entry_price = positions[ticker]['entry_price']\n                    shares = positions[ticker]['shares']\n                    value = sig['price'] * shares\n                    cash += value\n                    trades.append({\n                        'date': date,\n                        'ticker': ticker,\n                        'signal': 'SELL',\n                        'price': sig['price'],\n                        'pnl': (sig['price'] - entry_price) / entry_price\n                    })\n                    del positions[ticker]\n\n        # Calculate portfolio value\n        portfolio_value = cash\n        for ticker, pos in positions.items():\n            if ticker in stock_data and date in stock_data[ticker].index:\n                current_price = stock_data[ticker].loc[date, 'Close']\n                if not pd.isna(current_price):\n                    portfolio_value += current_price * pos['shares']\n\n        portfolio_values.append(portfolio_value)\n\n        # Calculate IBOV value\n        if date in ibov_data.index:\n            ibov_values.append(initial_capital * ibov_data['Close'].loc[date] / ibov_initial)\n\n    # Ensure same length\n    min_len = min(len(portfolio_values), len(ibov_values))\n    portfolio_values = portfolio_values[:min_len]\n    ibov_values = ibov_values[:min_len]\n\n    if min_len == 0:\n        print(\"ERROR: No valid data points", "return None\n\n    # Calculate metrics\n    portfolio_final = portfolio_values[-1]\n    ibov_final = ibov_values[-1]\n\n    portfolio_return = (portfolio_final - initial_capital) / initial_capital * 100\n    ibov_return = (ibov_final - initial_capital) / initial_capital * 100\n\n    portfolio_returns = pd.Series(portfolio_values).pct_change().dropna()\n    ibov_returns = pd.Series(ibov_values).pct_change().dropna()\n\n    portfolio_sharpe = calculate_sharpe(portfolio_returns)\n    ibov_sharpe = calculate_sharpe(ibov_returns)\n\n    portfolio_sortino = calculate_sortino(portfolio_returns)\n    ibov_sortino = calculate_sortino(ibov_returns)\n\n    portfolio_max_dd = calculate_max_drawdown(portfolio_values)\n    ibov_max_dd = calculate_max_drawdown(ibov_values)\n\n    portfolio_vol = portfolio_returns.std() * np.sqrt(252) * 100\n    ibov_vol = ibov_returns.std() * np.sqrt(252) * 100\n\n    # Win rate\n    winning_trades = sum(1 for t in trades if 'pnl' in t and t['pnl'] > 0)\n    total_trades = len([t for t in trades if 'pnl' in t])\n    win_rate = winning_trades / total_trades * 100 if total_trades > 0 else 0\n\n    # Profit factor\n    total_profit = sum(t['pnl'] for t in trades if 'pnl' in t and t['pnl'] > 0)\n    total_loss = abs(sum(t['pnl'] for t in trades if 'pnl' in t and t['pnl'] < 0))\n    profit_factor = total_profit / total_loss if total_loss > 0 else float('inf')\n\n    # Beta\n    if len(portfolio_returns) > 1 and len(ibov_returns) > 1:\n        aligned = pd.concat([portfolio_returns, ibov_returns], axis=1).dropna()\n        if len(aligned) > 1:\n            covariance = np.cov(aligned.iloc[:, 0], aligned.iloc[:, 1])[0, 1]\n            beta = covariance / np.var(aligned.iloc[:, 1])\n        else:\n            beta = 1.0\n    else:\n        beta = 1.0\n\n    # Correlation\n    if len(portfolio_returns) > 1 and len(ibov_returns) > 1:\n        corr = portfolio_returns.corr(ibov_returns)\n    else:\n        corr = 0.0\n\n    # VaR\n    portfolio_var = calculate_var(portfolio_returns)\n\n    # Tracking error\n    if len(portfolio_returns) > 1 and len(ibov_returns) > 1:\n        tracking_error = (portfolio_returns - ibov_returns).std() * np.sqrt(252) * 100\n    else:\n        tracking_error = 0.0\n\n    # Print results\n    print(f\"\n{'='*70}\")\n    print(f\"BACKTEST RESULTS SUMMARY\")\n    print(f\"{'='*70}\n\")\n\n    print(f", "Initial Capital: R${initial_capital:,.2f}\")\n    print(f\"\n--- Strategy Performance ---\")\n    print(f", "Final Value:       R${portfolio_final:,.2f}\")\n    print(f\"Total Return:      {portfolio_return:+.2f}%\")\n    print(f\"Sharpe Ratio:      {portfolio_sharpe:.2f}\")\n    print(f\"Sortino Ratio:     {portfolio_sortino:.2f}\")\n    print(f\"Max Drawdown:      {portfolio_max_dd:.2f}%\")\n    print(f\"Volatility:        {portfolio_vol:.2f}%\")\n    print(f\"Win Rate:         {win_rate:.1f}% ({winning_trades}/{total_trades} trades)\")\n    print(f\"Profit Factor:    {profit_factor:.2f}\")\n\n    print(f\"\n--- IBOV Benchmark ---\")\n    print(f", "Final Value:       R${ibov_final:,.2f}\")\n    print(f\"Total Return:      {ibov_return:+.2f}%\")\n    print(f\"Sharpe Ratio:      {ibov_sharpe:.2f}\")\n    print(f\"Sortino Ratio:     {ibov_sortino:.2f}\")\n    print(f\"Max Drawdown:      {ibov_max_dd:.2f}%\")\n    print(f\"Volatility:        {ibov_vol:.2f}%\")\n\n    print(f\"\n--- Alpha & Risk ---\")\n    alpha = portfolio_return - ibov_return\n    print(f\"Excess Return:    {alpha:+.2f}%\")\n    print(f\"Beta:             {beta:.2f}\")\n    print(f\"Correlation:      {corr:.2f}\")\n    print(f\"Tracking Error:   {tracking_error:.2f}%\")\n    print(f\"VaR (95%):        {portfolio_var:.2f}%\")\n\n    print(f\"\n--- Trades ---", "buy_signals = sum(1 for t in trades if t['signal'] == 'BUY')\n    sell_signals = sum(1 for t in trades if t['signal'] == 'SELL')\n    print(f\"BUY signals:   {buy_signals}\")\n    print(f\"SELL signals:  {sell_signals}", "Create plots\n    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(14, 10))\n\n    trading_days_plot = trading_days[60:min(len(portfolio_values)+60, len(trading_days))]\n\n    ax1.plot(trading_days_plot, portfolio_values[:len(trading_days_plot)], label='Strategy', linewidth=2, color='green')\n    ax1.plot(trading_days_plot, ibov_values[:len(trading_days_plot)], label='IBOV Index', linewidth=2, alpha=0.7, color='orange')\n    ax1.set_title('Portfolio Value vs IBOV (Nov 2025 - Present)', fontsize=14, fontweight='bold')\n    ax1.set_xlabel('Date', fontsize=12)\n    ax1.set_ylabel('Portfolio Value (R$)', fontsize=12)\n    ax1.legend()\n    ax1.grid(True, alpha=0.3)\n    ax1.axhline(y=initial_capital, color='red', linestyle='--', alpha=0.5, label='Break-even')\n\n    # Drawdown\n    portfolio_cummax = pd.Series(portfolio_values[:len(trading_days_plot)]).cummax()\n    portfolio_dd = -(portfolio_cummax - pd.Series(portfolio_values[:len(trading_days_plot)])) / portfolio_values[0] * 100\n\n    ibov_cummax = pd.Series(ibov_values[:len(trading_days_plot)]).cummax()\n    ibov_dd = -(ibov_cummax - pd.Series(ibov_values[:len(trading_days_plot)])) / ibov_values[0] * 100\n\n    ax2.fill_between(trading_days_plot, 0, portfolio_dd, alpha=0.3, color='green', label='Strategy DD')\n    ax2.fill_between(trading_days_plot, 0, ibov_dd, alpha=0.3, color='orange', label='IBOV DD')\n    ax2.set_title('Drawdown Comparison', fontsize=14, fontweight='bold')\n    ax2.set_xlabel('Date', fontsize=12)\n    ax2.set_ylabel('Drawdown (%)', fontsize=12)\n    ax2.legend()\n    ax2.grid(True, alpha=0.3)\n\n    plt.tight_layout()\n    plt.savefig('backtest_nov2025_results.png', dpi=150, bbox_inches='tight')\n    print(f\"\n\u2705 Plot saved to backtest_nov2025_results.png", "plt.close()\n\n    return {\n        'portfolio_return': portfolio_return,\n        'ibov_return': ibov_return,\n        'alpha': alpha,\n        'sharpe': portfolio_sharpe,\n        'sortino': portfolio_sortino,\n        'max_drawdown': portfolio_max_dd,\n        'volatility': portfolio_vol,\n        'win_rate': win_rate,\n        'profit_factor': profit_factor,\n        'beta': beta,\n        'correlation': corr,\n        'tracking_error': tracking_error,\n        'var': portfolio_var,\n        'trades': trades,\n        'portfolio_values': portfolio_values,\n        'ibov_values': ibov_values,\n        'trading_days': trading_days_plot\n    }\n\n\ndef main():\n    print(\"\n\" + \"=\"*70)\n    print(\"STOCK SIGNALS BACKTEST - NOV 2025 TO PRESENT\")\n    print(\"=", 70, "Get data\n    ibov_data, stock_data = get_data(IBOV_TOP_20, BACKTEST_START, BACKTEST_END)\n\n    if ibov_data is not None and stock_data is not None:\n        results = run_backtest(ibov_data, stock_data)\n\n        if results:\n            print(f\"\n{'='*70}\")\n            print(f\"\u2705 BACKTEST COMPLETE\")\n            print(f\"{'='*70}\")\n    else:\n        print(\"\n\u274c BACKTEST FAILED\")\n\n\nif __name__ == \"__main__", "main()"]]